 141→  "search",
 142→  "list",
 143→  "get",
 144→  "get-by-name",
 145→  "create",
 146→  "update",
 147→  "patch",
 148→  "delete",
 149→  "versions",
 150→  "files/read",
 151→  "files/download",
 152→  "files/write",
 153→  "files/remove",
 154→  "listing",
 155→  // agent 侧 tool 名叫 skill_extract, bridge 转发到 core force-archive
 156→  // (不依赖 messages, core 从 conversation buffer 拿)。见下方 sub === "extract" 分支。
 157→  "extract",
 158→]);
