312→      session_key: sessionKey,
313→      // Stamped by the runner so the judge's events carry them; null when the
314→      // artifacts were collected outside a run. Generalisation is counted as
315→      // distinct task ids, so a missing task id is a missing signal, not zero.
316→      run_id: runId,
317→      task_id: taskId,
318→      task_description: taskDescription,
319→      pre_change_files: preChangeFiles,
320→      diff,
321→      offered_content: [...(offeredBySession.get(sessionKey)?.values() ?? [])]
322→        .sort((a, b) => a.message_index - b.message_index),
323→      // Everything that came back from any tool, in arrival order. The judge
324→      // credits a token to a fetch only when that fetch is the token's
325→      // earliest delivery; anything earlier — another asset's body, a file
326→      // read, a snippet — means the credit cannot be given.
327→      delivered_content: [...(deliveredBySession.get(sessionKey)?.values() ?? [])]
328→        .sort((a, b) => a.message_index - b.message_index),
329→      operations,
330→      test_commands: operations.filter((o) => o.kind === "test_command").map((o) => o.locus),
331→      tool_call_args: operations.filter((o) => o.kind !== "diff_hunk").map((o) => o.text),
332→    });
333→  }
334→  return sessions;
335→}
336→
337→export function renderArtifacts(sessions) {
338→  const lines = ["# Collected artifacts", ""];
339→  if (sessions.length === 0) {
340→    lines.push("No session in the capture carried a tool call. Nothing to attribute against —");
341→    lines.push("**not** an empty result meaning nothing was used.");
342→    return lines.join("\n");
343→  }
344→  for (const s of sessions) {
345→    lines.push(`## ${s.session_key || "(no conversation id)"}`, "");
346→    lines.push(`  ${s.operations.length} operation(s), ${s.test_commands.length} of them checks`);
347→    lines.push(`  task description: ${s.task_description ? `${s.task_description.length} chars` : "not supplied"}`);
348→    lines.push(`  pre-change files: ${Object.keys(s.pre_change_files).length}`);
349→    lines.push("");
350→    for (const op of s.operations.slice(0, 25)) {
351→      const when = op.message_index == null ? op.ordering : `msg[${op.message_index}]`;
352→      const outcome = op.result
353→        ? (op.result.exit_code === null ? "" : ` exit=${op.result.exit_code}`)
354→        : " (no result)";
355→      lines.push(`  [${String(op.seq).padStart(2)}] ${op.kind.padEnd(12)} ${when}  ${op.tool_name || "-"}${outcome}`);
356→      lines.push(`       ${op.locus}`);
357→    }
358→    if (s.operations.length > 25) lines.push(`  … ${s.operations.length - 25} more`);
359→    lines.push("");
360→  }
361→  return lines.join("\n");
362→}
363→
364→// ── CLI ───────────────────────────────────────────────────────────
365→if (import.meta.url === `file://${process.argv[1]}`) {
366→  const args = process.argv.slice(2);
367→  const flag = (n) => args.filter((a) => a.startsWith(`--${n}=`)).map((a) => a.slice(n.length + 3));
368→  const capturePaths = args.filter((a) => !a.startsWith("--"));
369→  if (capturePaths.length === 0) {
370→    console.error("usage: node collect-artifacts.mjs <capture.jsonl ...> [--task=f] [--diff=f] [--pre=path=file] [--json]");
371→    process.exit(2);
372→  }
373→
374→  const preChangeFiles = {};
375→  for (const spec of flag("pre")) {
376→    const at = spec.indexOf("=");
377→    if (at < 0) { console.error(`--pre expects <path>=<file>, got ${spec}`); process.exit(2); }
378→    preChangeFiles[spec.slice(0, at)] = readFileSync(spec.slice(at + 1), "utf8");
379→  }
380→
381→  const sessions = collectArtifacts({
382→    captureEvents: capturePaths.flatMap((p) => parseJsonl(readFileSync(p, "utf8"))),
383→    taskDescription: flag("task").map((p) => readFileSync(p, "utf8")).join("\n"),
384→    diff: flag("diff").map((p) => readFileSync(p, "utf8")).join("\n"),
385→    preChangeFiles,
386→    runId: flag("run-id")[0] || null,
387→    taskId: flag("task-id")[0] || null,
388→  });
389→
390→  const outPath = "evaluation/attribution/artifacts/run-artifacts.json";
391→  mkdirSync(dirname(outPath), { recursive: true });
392→  writeFileSync(outPath, JSON.stringify(sessions, null, 2), "utf8");
393→
394→  if (args.includes("--json")) console.log(JSON.stringify(sessions, null, 2));
395→  else console.log(renderArtifacts(sessions), `\nWritten to ${outPath}`);
396→}
397→

 1→/**
 2→ * Regression: the exit status of a real CodeBuddy Bash result must survive into
 3→ * the operation list.
 4→ *
 5→ * The collection stage read the outcome with a lowercase `Exit code:` pattern,
 6→ * but the envelope CodeBuddy actually writes spells it `Exit Code:` — with a
 7→ * capital C, after the `Stderr:` section. Every real operation therefore
 8→ * carried `exit_code: null`, and the downstream classification of failed calls
 9→ * had nothing to classify by. The synthetic fixtures used elsewhere happen to
10→ * be built without a tail section at all, which is why the defect stayed
11→ * invisible to them: the test below feeds the envelope exactly as captured.
12→ */
13→
14→import { test } from "node:test";
15→import assert from "node:assert/strict";
16→
17→import { collectArtifacts, outcomeOf } from "./collect-artifacts.mjs";
18→
19→/** A Bash result in the shape the capture observed. */
20→const envelope = (exit, stderr = "(empty)") =>
21→  "Command: curl -sfk -X POST http://127.0.0.1:8096/skill-bridge/v3/skill/search -d '{\"query\":\"x\"}'\n"
22→  + 'Stdout: {"code":0,"data":{"items":[]}}\n'
23→  + `Stderr: ${stderr}\n`
24→  + `Exit Code: ${exit}\n`
25→  + "Signal: (none)";
26→
27→const capture = (messages) => [{
28→  event: "http.request",
29→  requestId: "req-1",
30→  timestamp: "2026-09-11T00:00:00Z",
31→  headers: { "x-conversation-id": "conv-1" },
32→  body: { json: { messages } },
33→}];
34→
35→const call = (id) => ({ role: "assistant", tool_calls: [{ id, function: { name: "Bash", arguments: "{}" } }] });
36→const result = (id, content) => ({ role: "tool", tool_call_id: id, content });
37→
38→test("a real Bash envelope reports its exit status in the operation list", () => {
39→  const [session] = collectArtifacts({
40→    captureEvents: capture([
41→      call("c1"),
42→      result("c1", envelope(0)),
43→      call("c2"),
44→      result("c2", envelope(28, "curl: (28) Operation timed out after 75000 ms")),
45→    ]),
46→  });
47→  const byCall = new Map(session.operations.map((op) => [op.call_id, op]));
48→
49→  assert.equal(byCall.get("c1").result.exit_code, 0, "a clean run must report exit 0");
50→  assert.equal(byCall.get("c2").result.exit_code, 28, "a failed run must report its code");
51→});
52→
53→test("the envelope's tail sections are not read back as stderr", () => {
54→  const ok = outcomeOf(envelope(0));
55→  assert.equal(ok.exit_code, 0);
56→  assert.equal(ok.stderr, "", "`(empty)` stderr reads back empty, without `Exit Code:`");
57→
58→  const failed = outcomeOf(envelope(7, "curl: (7) Failed to connect"));
59→  assert.equal(failed.exit_code, 7);
60→  assert.equal(failed.stderr, "curl: (7) Failed to connect", "stderr stops before `Exit Code:`");
61→});
62→

freshness.description:
Filter search results by time range. Supports d[N], m[N], and y[N] for the last N calendar days, months, and years:
- d[N]: N is an integer from 1 to 30;
- m[N]: N is an integer from 1 to 12;
- y[N]: N is an integer from 1 to 5.

N may be omitted and defaults to 1. The current partial calendar unit counts as 1. For example, d1 means today, m1 means the current month to date, and y1 means the current year to date. Omit this parameter to disable time filtering.

