   1→/**
   2→ * skill-bridge — reverse proxy for `<proxy>/skill-bridge/v3/skill/*` → core gateway.
   3→ *
   4→ * Why: the LLM uses Bash to curl skill operations (see <skill_tools> block in
   5→ * system prompt). We do NOT want the Bearer [REDACTED] to land in the prompt, and we
   6→ * want to stamp `(user_id, team_id, agent_id, task_id?)` from the session into
   7→ * outbound bodies so the LLM cannot fake identity.
   8→ *
   9→ * Behaviour:
  10→ *   1. Match path `/skill-bridge/v3/skill/<sub>`. Anything else → 404.
  11→ *   2. Refuse `_gc/versions` (ops-only).
  12→ *   3. Require initialized session (`x-conversation-id` keyed). Else 401.
  13→ *   4. Parse JSON body; merge IdFields from session, overwriting if conflict.
  14→ *   5. POST to `${coreSkill.endpoint}/v3/skill/<sub>` with auth headers.
  15→ *   6. Pass through status + JSON body unchanged.
  16→ *
  17→ * No streaming, no body logging (responses may contain SKILL.md content).
  18→ */
  19→
  20→import type { Context } from "hono";
  21→import type { Redis } from "ioredis";
  22→import { getSessionStore } from "../session/store.js";
  23→import type { BindingRepo } from "../db/binding-repo.js";
  24→import { KvBindingRepo } from "../db/kv-binding-repo.js";
  25→import { RedisBindingRepo } from "../db/binding-repo.js";
  26→// getSkillExtractTrigger / KvExtractStore 已随老链路一起删除。
  27→// 详见 handler-glue.ts 顶部注释 —— skill_extract 触发路径当前不可用,
  28→// core 侧后续会出手动归档接口, 到时 agent 工具再重新指向那个接口。
  29→import { getRedisClient } from "../db/redis-client.js";
  30→import { VersionPinRepo } from "./version-pin-repo.js";
  31→import { KvVersionPinRepo } from "./kv-version-pin-repo.js";
  32→import { getProxyStorage } from "../storage/factory.js";
  33→import { getMetadataClient } from "../meta/client.js";
  34→import type { ProxyConfig } from "../types.js";
  35→import { emitBridgeToolCallTelemetry, emitBridgeRejectTelemetry, agentSourceFromSessionKey } from "../memory/bridge-telemetry.js";
  36→import { getCoreSkillClient, type CoreSkillClient } from "./core-client.js";
  37→
  38→/**
  39→ * 二选一的 pin repo（KvVersionPinRepo 或 VersionPinRepo）——
  40→ * 接口对齐（getVersion/pinMany/upsertVersion），业务代码无需感知具体实现。
  41→ *
  42→ * 见 docs/design/2026-07-10-cos-ttl-nottl-split-plan.md §4.1：所有方法加
  43→ * `userId + agentSource` 两个必填参数。
  44→ *
  45→ * P4 (kernel-sts, docs/design/2026-07-12-cos-shark-sts-credential-plan.md)
  46→ * 之后又追加了 `spaceId` 首参 —— KvVersionPinRepo 的所有方法都要 5 个 seg
  47→ * 才能拼出正确的 COS key。老 VersionPinRepo (Redis) 用 wrapper 适配到同
  48→ * 一个 5 参签名，spaceId 段直接吞掉即可（Redis 版 key 里不带 spaceId）。
  49→ *
  50→ * 之前 4 参签名 + 直接把 KvVersionPinRepo 塞给 PinRepoLike 会导致：
  51→ *   spaceId ← ids.user_id
  52→ *   userId  ← ids.agent_source
  53→ *   agentSource ← sessionKey
  54→ *   sessionId ← skillId
  55→ * → key 完全错乱且丢租户隔离；节点 B 读永远 miss，症状匹配
  56→ *   "写到 COS 但另一节点看不到"。见 docs/design/2026-07-13-proxy-multinode-state-audit.md P0-1.
  57→ */
  58→interface PinRepoLike {
  59→  getVersion(
  60→    spaceId: string,
  61→    userId: string,
  62→    agentSource: string,
  63→    sessionId: string,
  64→    skillId: string,
  65→  ): Promise<number | null>;
  66→  pinMany(
  67→    spaceId: string,
  68→    userId: string,
  69→    agentSource: string,
  70→    sessionId: string,
  71→    pairs: Array<{ skillId: string; version: number }>,
  72→  ): Promise<void>;
  73→  upsertVersion(
  74→    spaceId: string,
  75→    userId: string,
  76→    agentSource: string,
  77→    sessionId: string,
  78→    skillId: string,
  79→    version: number,
  80→  ): Promise<void>;
  81→}
  82→
  83→/**
  84→ * 把 4 参 Redis-based VersionPinRepo 包成 5 参 PinRepoLike。
  85→ * Redis key schema (skill:vpin:<userId>:<agentSource>:<sessionId>) 里本来
  86→ * 就不带 spaceId —— 单实例 Redis 一般跟 kernel-sts space 是一对一或不重叠，
  87→ * 沿用旧行为，spaceId 参数直接丢弃。
  88→ */
  89→function adaptRedisPinRepo(inner: VersionPinRepo): PinRepoLike {
  90→  return {
  91→    getVersion: (_space, u, a, s, sk) => inner.getVersion(u, a, s, sk),
  92→    pinMany:    (_space, u, a, s, pairs) => inner.pinMany(u, a, s, pairs),
  93→    upsertVersion: (_space, u, a, s, sk, v) => inner.upsertVersion(u, a, s, sk, v),
  94→  };
  95→}
  96→
  97→/**
  98→ * 装配决策 —— 单一入口，让 skill-bridge 拿到"当前生效的"存储组合。
  99→ *
 100→ *   storage.enabled + mode!=off → 走 ProxyStorage (KvVersionPinRepo)
 101→ *   否则如果 redis.enabled       → 走 Redis (VersionPinRepo)
 102→ *   否则                          → null (in-memory 兜底)
 103→ *
 104→ * 曾经这里还装配 KvExtractStore / RedisExtractStore 给老链路
 105→ * SkillExtractTrigger 用, 已随老链路一起删除。
 106→ */
 107→export interface SkillBackingBundle {
 108→  redis: Redis | null;
 109→  pinRepo: PinRepoLike | null;
 110→  /**
 111→   * BindingRepo 直接从 SessionStore 拿(injection pipeline 装配时已注入),
 112→   * 不重新构造,保证 bridge L2 反查用的实例和 handler 写 binding 的实例一致
 113→   * —— 单元测试注入 SessionStore.setBindingRepo 后,bridge 也读同一个 mock。
 114→   */
 115→  bindingRepo: BindingRepo | null;
 116→}
 117→
 118→function resolveBacking(config: ProxyConfig): SkillBackingBundle {
 119→  const bindingRepo = getSessionStore().getBindingRepo() ?? null;
 120→  if (config.storage?.enabled) {
 121→    const storage = getProxyStorage(config.storage);
 122→    return {
 123→      redis: null,
 124→      pinRepo: new KvVersionPinRepo(storage),
 125→      bindingRepo: bindingRepo ?? new KvBindingRepo(storage),
 126→    };
 127→  }
 128→  const redis = config.redis?.enabled ? getRedisClient(config.redis) : null;
 129→  return {
 130→    redis,
 131→    pinRepo: redis ? adaptRedisPinRepo(new VersionPinRepo(redis, config.redis?.ttlSeconds)) : null,
 132→    bindingRepo: bindingRepo ?? (redis ? new RedisBindingRepo(redis) : null),
 133→  };
 134→}
 135→
 136→const TAG = "[skill-bridge]";
 137→
 138→// Subpaths the bridge will forward. Keep this allowlist tight on purpose so we
 139→// can audit exactly which core endpoints are reachable from the LLM.
 140→const ALLOWED_SUBPATHS = new Set<string>([
 141→  "search",
 142→  "list",
 143→  "get",
 144→  "get-by-name",
 145→  "create",
 146→  "update",
 147→  "patch",
 148→  "delete",
 149→  "versions",
 150→  "files/read",
 151→  "files/download",
 152→  "files/write",
 153→  "files/remove",
 154→  "listing",
 155→  // agent 侧 tool 名叫 skill_extract, bridge 转发到 core force-archive
 156→  // (不依赖 messages, core 从 conversation buffer 拿)。见下方 sub === "extract" 分支。
 157→  "extract",
 158→]);
 159→
 160→/**
 161→ * Write subpaths — rejected when `allowLlmWrite=false`.
 162→ *
 163→ * `extract` is here on purpose. It does not edit a skill, but it makes the
 164→ * extractor create one from the current conversation, and a skill created that
 165→ * way lands in the team pool exactly like one written through `create`. A
 166→ * read-only session that can still mint skills is not read-only; the 2026-09-06
 167→ * instruction audit found the gate covering the six editing subpaths and
 168→ * leaving this one open.
 169→ */
 170→const WRITE_SUBPATHS = new Set<string>([
 171→  "create",
 172→  "update",
 173→  "patch",
 174→  "delete",
 175→  "files/write",
 176→  "files/remove",
 177→  "extract",
 178→]);
 179→
 180→/** True when `sub` changes the skill pool and must be refused under `allowLlmWrite=false`. */
 181→export function isWriteSubpath(sub: string): boolean {
 182→  return WRITE_SUBPATHS.has(sub);
 183→}
 184→
 185→// Note: 曾经有 RESET_EXTRACT_SUBPATHS 用来在 write 成功或 extract 完成后
 186→// 清零 proxy 侧 buffer 计数器 (老链路 KvExtractStore)。老链路删除后计数器
 187→// 也没了, 该常量随之删除。
 188→
 189→/**
 190→ * Version pinning — see docs/design/2026-06-29-skill-version-pinning.md.
 191→ *
 192→ * Read ops: proxy injects `version` into outbound so plugin returns the pinned
 193→ *   version's content (instead of head). Cross-tool consistency.
 194→ * Write ops: proxy injects `expected_version` for optimistic locking. If head
 195→ *   moved (external update), plugin returns 40901 SKILL_VERSION_STALE.
 196→ * Delete / create / extract / search / listing / list / versions / files-download
 197→ *   do NOT participate (soft-delete doesn't bump version; others are stateless).
 198→ */
 199→const READ_VERSION_OPS = new Set<string>(["get", "files/read"]);
 200→
 201→/**
 202→ * Read ops that must honour the same visibility whitelist as `search`.
 203→ *
 204→ * Before this, the three read paths disagreed about scope: `search` was
 205→ * team-visible (whitelist A ∪ B), `get-by-name` was owner-only (core looks up
 206→ * by (team, caller agent, name)), and `get` / `files/read` were team-wide with
 207→ * no visibility check at all (core scopes by team only). Two consequences,
 208→ * both seen in a real run: a consumer could *find* another agent's team-shared
 209→ * skill via search and then get 40401 reading it by name; and the same
 210→ * consumer could read any skill in the team by id — private ones included.
 211→ */
 212→const READ_VISIBILITY_OPS = new Set<string>(["get", "get-by-name", "files/read"]);
 213→const WRITE_LOCK_OPS = new Set<string>([
 214→  "update",
 215→  "patch",
 216→  "files/write",
 217→  "files/remove",
 218→]);
 219→
 220→interface SessionIdFields {
 221→  user_id: string;
 222→  team_id: string;
 223→  agent_id: string;
 224→  /**
 225→   * URL 路径侧的 agentSource（`claude-code` / `codebuddy` ...）—— 用于
 226→   * Repo 三段隔离键。从 SessionStore 里存储 session 的 keyId 反解出来
 227→   * （keyId 形如 `${agentSource}:${sessionId}`）。
 228→   */
 229→  agent_source: string;
 230→  /**
 231→   * Kernel tenant/instance ID for `x-tdai-service-id`. Extracted from
 232→   * `SessionInfo.space_id` (which itself was captured from the original
 233→   * request path `/{agent}/{spaceId}/...`). Undefined for legacy sessions
 234→   * created before space_id tracking — caller falls back to
 235→   * `config.coreSkill.serviceId`.
 236→   */
 237→  space_id?: string;
 238→  /**
 239→   * User API key (`x-tdai-user-key`). Captured during session init from the
 240→   * upstream request's api key exchange. Required by kernel /v3/meta/* endpoints
 241→   * to enforce per-user ACL/visibility. Missing here means the session upstream
 242→   * bypassed apikey verification — that's a programming bug, not a rejectable
 243→   * runtime state; team-wide search returns 500 rather than silently opening up.
 244→   */
 245→  user_key?: string;
 246→  /**
 247→   * Composite key actually used to load state from SessionStore
 248→   * (`${agentSource}:${sessionId}`). 用于埋点侧对齐 session_init_logs 的
 249→   * session_key —— 埋点不能猜前缀，必须用真实命中的 key。
 250→   */
 251→  composite_key?: string;
 252→}
 253→
 254→/**
 255→ * Bridge 只吃 2 个 header:
 256→ *   - x-conversation-id (或 x-session-id / x-chat-id / x-thread-id) → sessionId
 257→ *   - x-tdai-service-id → spaceId
 258→ *
 259→ * 不再依赖 Authorization 反查 userId —— 见 docs/design/2026-08-03-binding-flatten.md,
 260→ * L2 fallthrough 走拍平的 (spaceId, sessionId) → binding.json 直接 stamp。
 261→ */
 262→function deriveSessionId(c: Context): string | null {
 263→  return (
 264→    c.req.header("x-conversation-id") ??
 265→    c.req.header("x-session-id") ??
 266→    c.req.header("x-chat-id") ??
 267→    c.req.header("x-thread-id") ??
 268→    null
 269→  );
 270→}
 271→
 272→function stateToIdFields(
 273→  state: import("../session/types.js").SessionInitState | undefined,
 274→  matchedKey: string,
 275→): SessionIdFields | null {
 276→  if (!state || state.status !== "initialized" || !state.sessionInfo) return null;
 277→  const s = state.sessionInfo;
 278→  if (!s.user_id || !s.team_id || !s.agent_id) return null;
 279→  // agentSource 从 matchedKey 反解(命中的 L1 key 形如 `${agentSource}:${sessionId}`);
 280→  // L2b 分支直接从 binding.agentSource 拿(见 bindingToIdFields)。
 281→  const colonIdx = matchedKey.indexOf(":");
 282→  const agentSource = colonIdx > 0 ? matchedKey.slice(0, colonIdx) : "claude-code";
 283→  return {
 284→    user_id: s.user_id,
 285→    team_id: s.team_id,
 286→    agent_id: s.agent_id,
 287→    agent_source: agentSource,
 288→    space_id: s.space_id,
 289→    user_key: s.user_key,
 290→    composite_key: matchedKey,
 291→  };
 292→}
 293→
 294→function bindingToIdFields(
 295→  binding: import("../db/binding-repo.js").SessionBinding,
 296→  spaceId: string,
 297→  sessionId: string,
 298→): SessionIdFields | null {
 299→  if (binding.outcome !== "initialized") return null;
 300→  if (!binding.userId || !binding.teamId || !binding.agentId) return null;
 301→  const agentSource = binding.agentSource || "claude-code";
 302→  return {
 303→    user_id: binding.userId,
 304→    team_id: binding.teamId,
 305→    agent_id: binding.agentId,
 306→    agent_source: agentSource,
 307→    space_id: spaceId,
 308→    user_key: binding.userKey,
 309→    composite_key: `${agentSource}:${sessionId}`,
 310→  };
 311→}
 312→
 313→/**
 314→ * L1: 先按 bare sessionId 试(handler.ts 存的 keyId 是 `${agentSource}:${sessionId}`,
 315→ * bridge curl 拿不到 agentSource,所以按候选前缀顺序探)。
 316→ *
 317→ * ⚠️ 候选轮询是过渡期兼容:同 pod 内主对话链路建过 session, L1 Map 里的 key 带
 318→ * agentSource 前缀,bare sessionId 命中不到。方案 B 拍平后 L2b binding 直接命中
 319→ * 2 段 key,不再需要前缀轮询;这里 L1 保留是为了 L2b 出问题时,仍能从内存 L1
 320→ * 恢复而不 401。
 321→ */
 322→function loadSessionIdsL1(sessionId: string): SessionIdFields | null {
 323→  const candidates = sessionId.includes(":")
 324→    ? [sessionId]
 325→    : [sessionId, `codebuddy:${sessionId}`, `claude-code:${sessionId}`];
 326→  for (const k of candidates) {
 327→    const s = getSessionStore().get(k);
 328→    if (s) {
 329→      const fields = stateToIdFields(s, k);
 330→      if (fields) return fields;
 331→    }
 332→  }
 333→  return null;
 334→}
 335→
 336→/**
 337→ * L2 fallthrough —— 拍平后只吃 (spaceId, sessionId)。见
 338→ * docs/design/2026-08-03-binding-flatten.md。
 339→ *
 340→ * 不再走 verifyUserKey + getOrRecover 那条 4 段路径。原因:
 341→ *   1) bridge curl 模板没塞 Authorization: Bearer,verify 拿不到 userId
 342→ *   2) 拍平后 binding.json 里已经存了 user_id/team_id/agent_id/agent_source/user_key,
 343→ *      一次 GET 就够,不需要再补 kernel getAgent/getTask
 344→ */
 345→async function loadSessionIdsL2(
 346→  bindingRepo: BindingRepo | null,
 347→  spaceId: string,
 348→  sessionId: string,
 349→): Promise<SessionIdFields | null> {
 350→  if (!bindingRepo) return null;
 351→  try {
 352→    const binding = await bindingRepo.getBinding(spaceId, sessionId);
 353→    if (!binding) return null;
 354→    return bindingToIdFields(binding, spaceId, sessionId);
 355→  } catch (err) {
 356→    console.warn(`${TAG} L2 getBinding error space=${spaceId} sid=${sessionId}: ${(err as Error).message}`);
 357→    return null;
 358→  }
 359→}
 360→
 361→function envelope(code: number, message: string, httpStatus = 200) {
 362→  return new Response(
 363→    JSON.stringify({ code, message, request_id: `bridge-${Date.now()}` }),
 364→    { status: httpStatus, headers: { "content-type": "application/json" } },
 365→  );
 366→}
 367→
 368→function extractSubpath(path: string): string | null {
 369→  // path comes in as `/skill-bridge/v3/skill/<sub...>` (or the segment after
 370→  // the bridge prefix, depending on how it was mounted).
 371→  const m = path.match(/^\/skill-bridge\/v3\/skill\/(.+)$/);
 372→  if (!m) return null;
 373→  return m[1].replace(/\/+$/, "");
 374→}
 375→
 376→/**
 377→ * Contract for the ACL/visibility resolver invoked by team-wide search.
 378→ * Production implementation calls MetadataClient.listAccessibleAssets with
 379→ * asset_type='skill' + action='read' + visibility='team'. Tests inject a stub.
 380→ *
 381→ * No caching: skill_search is low-frequency (0-3 times per session), meta call
 382→ * is ~tens-of-ms next to a seconds-long LLM turn, and a cache would introduce
 383→ * a stale window that contradicts the panel (a visibility flip on the panel
 384→ * should be visible to the LLM's next search immediately).
 385→ */
 386→export type VisibleSkillIdsResolver = (input: {
 387→  user_id: string;
 388→  team_id: string;
 389→  user_key: string;
 390→  space_id?: string;
 391→}) => Promise<{
 392→  ids: string[];
 393→  /**
 394→   * The same assets with their names, when the resolver has them. Optional so
 395→   * a resolver that returns ids alone (older callers, tests) keeps working;
 396→   * without it get-by-name can resolve only the caller's own skills.
 397→   */
 398→  assets?: Array<{ asset_id: string; name?: string; owner_user_id?: string }>;
 399→}>;
 400→
 401→export interface SkillBridgeDeps {
 402→  /** Override fetcher (tests). */
 403→  fetcher?: typeof fetch;
 404→  /** Override `Date.now` (tests). */
 405→  now?: () => number;
 406→  /**
 407→   * Override the visibility whitelist lookup (tests). When omitted, the bridge
 408→   * uses the production resolver that calls kernel /v3/meta/asset/list-accessible.
 409→   */
 410→  resolveVisibleSkillIds?: VisibleSkillIdsResolver;
 411→  /**
 412→   * Override the core skill client (tests). When omitted, uses the singleton
 413→   * built from config. Used by team-search to enumerate agent-owned skills
 414→   * (B) and already-injected skills (C) — see whitelist composition below.
 415→   */
 416→  coreClient?: CoreSkillClient;
 417→}
 418→
 419→/** A team skill as `listSkills` reports it, reduced to what visibility needs. */
 420→export interface TeamSkillRef {
 421→  skill_id: string;
 422→  name: string;
 423→  owner_agent_id?: string;
 424→}
 425→
 426→export type ReadVisibilityDecision =
 427→  | { kind: "forward" }
 428→  | { kind: "rewrite"; skillId: string }
 429→  | { kind: "reject"; reason: string; message: string };
 430→
 431→/**
 432→ * Decide how a read op proceeds, given the visibility whitelist.
 433→ *
 434→ * Pure: no I/O, no session — so it can be tested directly, which matters
 435→ * because this is an authorization decision and the handler around it needs a
 436→ * live session to exercise.
 437→ *
 438→ *   get / files/read   the id must be in the whitelist, else reject. This is
 439→ *                      what closes the bypass: core scopes these by team only.
 440→ *   get-by-name        resolve the name among *visible* team skills and rewrite
 441→ *                      to `get` by id — that is what lets a consumer read a
 442→ *                      skill it found through search. Prefer the caller's own
 443→ *                      skill on a name clash; with no own skill and more than
 444→ *                      one visible match, do not guess: forward unchanged and
 445→ *                      let core answer as it always has.
 446→ *   anything else      forward unchanged.
 447→ *
 448→ * A name that resolves to nothing visible is also forwarded unchanged rather
 449→ * than rejected: core's owner-scoped lookup will 40401 exactly as before, and
 450→ * a private skill of another agent stays invisible — its existence is not
 451→ * revealed by a different error code. Likewise a rejected `get` says only
 452→ * "not visible", whether the id is private or does not exist.
 453→ */
 454→export function decideReadVisibility(input: {
 455→  sub: string;
 456→  inboundBody: Record<string, unknown>;
 457→  whitelist: Set<string>;
 458→  teamSkills: TeamSkillRef[];
 459→  callerAgentId: string;
 460→}): ReadVisibilityDecision {
 461→  const { sub, inboundBody, whitelist, teamSkills, callerAgentId } = input;
 462→
 463→  if (sub === "get" || sub === "files/read") {
 464→    const skillId = typeof inboundBody.skill_id === "string" ? inboundBody.skill_id : "";
 465→    if (!skillId) return { kind: "forward" }; // schema validation upstream will reject
 466→    if (whitelist.has(skillId)) return { kind: "forward" };
 467→    return {
 468→      kind: "reject",
 469→      reason: "not_visible",
 470→      message: `skill ${skillId} is not visible to agent ${callerAgentId}`,
 471→    };
 472→  }
 473→
 474→  if (sub === "get-by-name") {
 475→    const name = typeof inboundBody.skill_name === "string" ? inboundBody.skill_name : "";
 476→    if (!name) return { kind: "forward" };
 477→    const visible = teamSkills.filter((t) => t.name === name && whitelist.has(t.skill_id));
 478→    if (visible.length === 0) return { kind: "forward" };
 479→    const own = visible.find((t) => t.owner_agent_id === callerAgentId);
 480→    if (own) return { kind: "rewrite", skillId: own.skill_id };
 481→    if (visible.length === 1) return { kind: "rewrite", skillId: visible[0].skill_id };
 482→    return { kind: "forward" };
 483→  }
 484→
 485→  return { kind: "forward" };
 486→}
 487→
 488→/**
 489→ * The read whitelist for read ops, with names attached so `get-by-name` can
 490→ * resolve across it.
 491→ *
 492→ *   A = meta list-accessible(purpose='use')   every asset this user may read
 493→ *       on the model's path: admitted (approved) ones only, the caller's own
 494→ *       included — and it carries each asset's name, which is where names
 495→ *       for other agents' skills come from
 496→ *   B = coreClient.listSkills(team, caller agent)   the caller's own skills,
 497→ *       used for names and agent ids only
 498→ *
 499→ * Until 2026-09-08 the whitelist was A(visibility='team') ∪ B, and B let the
 500→ * caller's own candidates and rejected skills back in: admission is a
 501→ * property of the asset, not of who is asking, so B no longer widens the
 502→ * whitelist. Core applies the same rule on its side (skill-handlers
 503→ * admissionFilter); this list is the proxy's own copy of it, so a stale
 504→ * proxy fails closed rather than open.
 505→ *
 506→ * There is deliberately no team-wide `listSkills` here. An earlier version
 507→ * called it with team_id alone, and CoreSkillClient.normalizeTeamAgent fills
 508→ * an empty agent_id with "default" — so the call listed the skills owned by an
 509→ * agent named "default": none, and no error. Name resolution then found
 510→ * nothing, get-by-name was forwarded unchanged, and the consumer got 40401
 511→ * exactly as before the fix, with the fix silently doing nothing.
 512→ *
 513→ * Failure policy mirrors search: A failing is fail-closed (an empty whitelist,
 514→ * never an unfiltered read); B failing degrades to A only.
 515→ */
 516→export async function computeReadWhitelist(input: {
 517→  ids: { user_id: string; team_id: string; agent_id: string; user_key?: string; space_id?: string };
 518→  resolver: VisibleSkillIdsResolver;
 519→  coreClient: Pick<CoreSkillClient, "listSkills">;
 520→}): Promise<{ ok: true; whitelist: Set<string>; teamSkills: TeamSkillRef[]; namesFromA: boolean } | { ok: false; err: Error }> {
 521→  const { ids, resolver, coreClient } = input;
 522→
 523→  const promiseA = resolver({
 524→    user_id: ids.user_id, team_id: ids.team_id, user_key: ids.user_key ?? "", space_id: ids.space_id,
 525→  }).then((r) => ({ ok: true as const, ids: r.ids, assets: r.assets ?? [] }))
 526→    .catch((err) => ({ ok: false as const, err: err as Error }));
 527→
 528→  const promiseB = coreClient.listSkills(
 529→    { team_id: ids.team_id, agent_id: ids.agent_id, pagination: { limit: 1000 } },
 530→    { serviceId: ids.space_id },
 531→  ).then((r) => r.items.map((s) => ({ skill_id: s.skill_id, name: s.name, owner_agent_id: s.owner_agent_id ?? ids.agent_id })))
 532→    .catch((err) => {
 533→      console.warn(`${TAG} read whitelist own-skills list (B) failed, treating as empty: ${(err as Error).message}`);
 534→      return [] as TeamSkillRef[];
 535→    });
 536→
 537→  const [aResult, own] = await Promise.all([promiseA, promiseB]);
 538→  if (!aResult.ok) return { ok: false, err: aResult.err };
 539→
 540→  const whitelist = new Set<string>(aResult.ids);
 541→  // Own skills contribute names and agent ids, never ids the whitelist lacks.
 542→  const ownAdmitted = own.filter((s) => whitelist.has(s.skill_id));
 543→  const ownIds = new Set(ownAdmitted.map((s) => s.skill_id));
 544→  // A's entries that are not the caller's own carry no agent id from meta, so
 545→  // they are recorded as "someone else's" — which is all the clash rule needs.
 546→  const fromA: TeamSkillRef[] = aResult.assets
 547→    .filter((a) => a.name && !ownIds.has(a.asset_id))
 548→    .map((a) => ({ skill_id: a.asset_id, name: a.name as string, owner_agent_id: undefined }));
 549→
 550→  return {
 551→    ok: true,
 552→    whitelist,
 553→    teamSkills: [...ownAdmitted, ...fromA],
 554→    namesFromA: aResult.assets.length > 0,
 555→  };
 556→}
 557→
 558→/**
 559→ * Plugin's hard upper bound for /v3/skill/search `top_k` (see
 560→ * searchRequestSchema in plugin — z.number().int().min(1).max(50)).
 561→ *
 562→ * We overfetch to this cap on team-wide search so the response-side visibility
 563→ * filter has room to drop non-whitelisted items without starving the LLM. The
 564→ * BM25 top-50 is a strict superset of top-N (for N ≤ 50), so slicing after the
 565→ * filter yields the same ordering as if plugin had returned exactly N.
 566→ *
 567→ * Cost: ~20KB of extra JSON per team search + a Set.has per item. Trivial.
 568→ * Failure mode: only if the team has more than 50 team-visible skills that
 569→ * match the query AND enough of the top-50 hits are non-whitelisted to leave
 570→ * fewer than N — vanishingly unlikely for the current corpus size. If it ever
 571→ * matters, raise plugin's cap; this stays as-is.
 572→ *
 573→ * TODO(upgrade): 长期来看，如果观察到 team search 过滤后剩余条数常 < 用户
 574→ * top_k（whitelist merged 显著大于 50，或 filter 命中率 P95 < 0.2），说明
 575→ * 该 team 的 skill 池已把 top-50 撑爆，overfetch 兜不住 → 升级为请求侧
 576→ * 过滤（proxy 传 `skill_ids: [...]` → core 在 pool 内精确检索）。
 577→ * 见 `docs/design/2026-08-10-skill-search-scope-fix.md` §3 Plan A。
 578→ */
 579→const PLUGIN_SEARCH_HARD_TOPK = 50;
 580→
 581→/** Default `top_k` the LLM sees if it doesn't specify one. Matches plugin default. */
 582→const DEFAULT_SEARCH_TOPK = 10;
 583→
 584→/**
 585→ * Default resolver: call kernel /v3/meta/asset/list-accessible each time.
 586→ *
 587→ * Failure: kernel call throws → propagate; skill-bridge fail-closes with
 588→ * empty items so LLM never sees an unfiltered team search.
 589→ */
 590→function defaultVisibleSkillIdsResolver(
 591→  config: ProxyConfig,
 592→): VisibleSkillIdsResolver {
 593→  return async ({ user_id, team_id, user_key, space_id }) => {
 594→    // Use the real space_id from the request (kernel routes tenants by
 595→    // x-tdai-service-id header) — fall back to config only for legacy sessions.
 596→    const serviceId = space_id || config.coreSkill.serviceId;
 597→    const client = getMetadataClient(config.coreSkill, serviceId, user_key);
 598→    const assets = await client.listAccessibleAssets({
 599→      user_id,
 600→      team_id,
 601→      asset_type: "skill",
 602→      action: "read",
 603→      // The model's path (2026-09-08): admitted assets this user may read —
 604→      // team-shared ones and the caller's own, private included. Other
 605→      // people's private and ACL-restricted skills stay out because the
 606→      // kernel's permission check keeps them out, not because of a
 607→      // visibility filter here; candidates and rejected skills stay out
 608→      // whoever owns them.
 609→      purpose: "use",
 610→    });
 611→    // For skill assets, asset_id === skill_id by kernel convention.
 612→    return {
 613→      ids: assets.map((a) => a.asset_id),
 614→      assets: assets.map((a) => ({ asset_id: a.asset_id, name: a.name, owner_user_id: a.owner_user_id })),
 615→    };
 616→  };
 617→}
 618→
 619→/**
 620→ * Build a Hono-compatible handler. Hono passes its `Context`; we use `c.req.raw`
 621→ * to get the underlying Request, then issue an outbound fetch and adapt the
 622→ * response back to a `Response`.
 623→ */
 624→export function createSkillBridgeHandler(
 625→  config: ProxyConfig,
 626→  deps: SkillBridgeDeps = {},
 627→): (c: Context) => Promise<Response> {
 628→  const fetcher = deps.fetcher ?? globalThis.fetch.bind(globalThis);
 629→
 630→  return async (c: Context): Promise<Response> => {
 631→    const t0 = (deps.now ?? Date.now)();
 632→
 633→    const path = new URL(c.req.url).pathname;
 634→    const sub = extractSubpath(path);
 635→    // 前置校验早退埋点: 每个 return 前都发一条 reject_reason 非空的 bridge_call。
 636→    // sessionKey 此刻可能还没派生, 允许传 "" (helper 兜底 agentSource='unknown')。
 637→    if (!sub) {
 638→      emitBridgeRejectTelemetry({
 639→        sessionKey: "", bridgeSource: "skill-bridge",
 640→        rejectReason: "unknown_path", httpStatus: 404,
 641→      });
 642→      return envelope(40401, `${TAG} unknown path ${path}`, 404);
 643→    }
 644→    if (!ALLOWED_SUBPATHS.has(sub)) {
 645→      emitBridgeRejectTelemetry({
 646→        sessionKey: "", bridgeSource: "skill-bridge",
 647→        rejectReason: "subpath_forbidden", httpStatus: 403,
 648→        executedEndpoint: sub,
 649→      });
 650→      return envelope(40301, `${TAG} subpath '${sub}' not allowed via bridge`, 403);
 651→    }
 652→    if (c.req.method !== "POST") {
 653→      emitBridgeRejectTelemetry({
 654→        sessionKey: "", bridgeSource: "skill-bridge",
 655→        rejectReason: "method_not_allowed", httpStatus: 405,
 656→        executedEndpoint: sub,
 657→      });
 658→      return envelope(40501, `${TAG} method ${c.req.method} not allowed`, 405);
 659→    }
 660→
 661→    const ct = c.req.header("content-type") ?? "";
 662→    if (!ct.toLowerCase().includes("application/json")) {
 663→      emitBridgeRejectTelemetry({
 664→        sessionKey: "", bridgeSource: "skill-bridge",
 665→        rejectReason: "content_type_invalid", httpStatus: 415,
 666→        executedEndpoint: sub,
 667→      });
 668→      return envelope(41501, `${TAG} content-type must be application/json`, 415);
 669→    }
 670→
 671→    // Session must be initialized — IdFields come from there.
 672→    // curl 模板只带 (x-conversation-id, x-tdai-service-id) 两个 header;
 673→    // L1 miss 时用它俩去 nottl/<spaceId>/<sessionId>/binding.json 反查。
 674→    const sessionKey = deriveSessionId(c);
 675→    if (!sessionKey) {
 676→      emitBridgeRejectTelemetry({
 677→        sessionKey: "", bridgeSource: "skill-bridge",
 678→        rejectReason: "missing_conversation_id", httpStatus: 401,
 679→        executedEndpoint: sub,
 680→      });
 681→      return envelope(40101, `${TAG} missing x-conversation-id (or x-session-id / x-chat-id / x-thread-id) header`, 401);
 682→    }
 683→    const spaceId = c.req.header("x-tdai-service-id")
 684→      ?? config.tdai?.serviceId
 685→      ?? config.coreSkill?.serviceId
 686→      ?? "";
 687→
 688→    // Backing storage for extract trigger + version pin.
