{"content": "import { test } from "node:test";
import assert from "node:assert/strict";
import { fetchResource } from "./fetch-resource.mjs";

const BRIDGE = "http://bridge.test/skill-bridge/v3/skill";

/** A fetcher that records its call and answers with one JSON envelope. */
function stub(envelope, { status = 200 } = {}) {
  const calls = [];
  const fetcher = async (url, init) => {
    calls.push({ url, init });
    return new Response(JSON.stringify(envelope), {
      status,
      headers: { "content-type": "application/json" },
    });
  };
  return { fetcher, calls };
}

test("returns the resource's bytes and asks for it by id and path", async () => {
  const { fetcher, calls } = stub({
    code: 0,
    message: "ok",
    data: { path: "doc.md", content: Buffer.from("hello\n").toString("base64"), encoding: "base64", size_bytes: 6 },
  });
  const buf = await fetchResource({ skillId: "skl-1", path: "doc.md", bridgeBase: BRIDGE, fetcher });

  assert.ok(Buffer.isBuffer(buf));
  assert.equal(buf.toString("utf8"), "hello\n");
  assert.equal(calls[0].url, `${BRIDGE}/files/read`);
  const body = JSON.parse(calls[0].init.body);
  assert.equal(body.skill_id, "skl-1");
  assert.equal(body.path, "doc.md");
});

test("an empty resource is a zero-byte Buffer, not an error", async () => {
  const { fetcher } = stub({
    code: 0,
    message: "ok",
    data: { path: "empty.md", content: "", encoding: "utf-8", size_bytes: 0 },
  });
  const buf = await fetchResource({ skillId: "skl-1", path: "empty.md", bridgeBase: BRIDGE, fetcher });

  assert.ok(Buffer.isBuffer(buf));
  assert.equal(buf.length, 0);
});

test("an error envelope throws with the envelope's message", async () => {
  const { fetcher } = stub({ code: 40401, message: "skill not found", request_id: "req-1" });
  await assert.rejects(
    () => fetchResource({ skillId: "skl-x", path: "SKILL.md", bridgeBase: BRIDGE, fetcher }),
    /skill not found/,
  );
});

test("omitting fetcher falls back to globalThis.fetch", async () => {
  const real = globalThis.fetch;
  const { fetcher, calls } = stub({
    code: 0,
    message: "ok",
    data: { path: "a.txt", content: Buffer.from("A").toString("base64"), encoding: "base64", size_bytes: 1 },
  });
  globalThis.fetch = fetcher;
  try {
    const buf = await fetchResource({ skillId: "skl-1", path: "a.txt", bridgeBase: BRIDGE });
    assert.equal(buf.toString("utf8"), "A");
    assert.equal(calls.length, 1);
  } finally {
    globalThis.fetch = real;
  }
});
